package sentinel.persistence;

import java.nio.channels.FileChannel;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import sentinel.analysis.*;
import sentinel.application.*;
import sentinel.data.*;
import sentinel.domain.*;
import sentinel.events.*;
import sentinel.planning.*;
import sentinel.reporting.*;
import sentinel.tools.*;
import static org.junit.jupiter.api.Assertions.*;

class PersistenceIntegrationTest {
    @TempDir Path temp;
    private final Instant time=Instant.parse("2026-10-22T12:00:00Z");
    private DatasetStore store;private ToolExecutor tools;private AgentEngine engine;
    @BeforeEach void setup(){store=new DatasetStore("demo",Clock.fixed(time.plusSeconds(7*86400),ZoneOffset.UTC),Duration.ofDays(30));store.ingest(new ImportBatch(List.of(event("a",0))));tools=ToolExecutor.local(store);engine=engine(store,tools);}
    @AfterEach void close(){tools.close();}
    private Event event(String id,long seconds){return new Event(id,time.plusSeconds(seconds),"login","alice","192.0.2.10","host","success","fixture#/"+id,"pending");}
    private AgentEngine engine(DatasetStore data,ToolExecutor executor){var analysis=new AnalysisService(p->JsonCodec.encode(new AnalysisService.ShortSynthesis("analysis-v1",new AnalysisService.ShortHypothesis("Review login","E1",List.of(),"LOW","Synthetic"),new AnalysisService.ShortRecommendation("REVIEW","Review cited login","E1","LOW","Approval"))),new TimelineBuilder(),new RuleSeverityPolicy(),data);return new AgentEngine(c->null,executor,analysis,new EventBus(),data);}
    private Investigation ready(){var scope=new CaseScope("demo",store.currentVersion(),"alice",time,time.plusSeconds(3600));var i=new Investigation(new Request("Investigate alice",scope));engine.acceptRulePlan(i);return i;}
    private Path casePath(Path root,UUID id){return root.resolve(id+".json");}
    @Test void caseRoundtripRetainsAssessmentEvidenceVersionsAndAudit(){var i=ready();engine.run(i);var repository=new JsonCaseRepository(temp.resolve("cases"));assertEquals(i.snapshot().caseVersion(),repository.save(i.snapshot()));assertEquals(i.snapshot(),repository.load(i.snapshot().id()).snapshot());assertEquals(i.snapshot().id(),repository.list().get(0).id());}
    @Test void equalSnapshotSaveIsIdempotentButStaleOrConflictingVersionIsRejected(){var i=ready();var repo=new JsonCaseRepository(temp);var old=i.snapshot();repo.save(old);repo.save(old);i.recordAction("CHECK","OK",List.of());repo.save(i.snapshot());assertThrows(IllegalStateException.class,()->repo.save(old));var other=Investigation.restore(old);other.recordAction("DIFFERENT","OK",List.of());assertThrows(IllegalStateException.class,()->repo.save(other.snapshot()));assertEquals(i.snapshot(),repo.load(i.snapshot().id()).snapshot());}
    @Test void anotherWriterLockRejectsSaveWithoutChangingFile()throws Exception{var i=ready();var repo=new JsonCaseRepository(temp);repo.save(i.snapshot());String before=Files.readString(casePath(temp,i.snapshot().id()));try(var channel=FileChannel.open(temp.resolve(i.snapshot().id()+".lock"),StandardOpenOption.WRITE);var lock=channel.lock()){i.recordAction("CHECK","OK",List.of());assertThrows(IllegalStateException.class,()->repo.save(i.snapshot()));}assertEquals(before,Files.readString(casePath(temp,i.snapshot().id())));}
    @Test void unknownCaseFieldsAndUnsupportedSchemaAreRejected()throws Exception{var i=ready();var repo=new JsonCaseRepository(temp);repo.save(i.snapshot());Path p=casePath(temp,i.snapshot().id());String valid=Files.readString(p);Files.writeString(p,valid.replaceFirst("\\{","{\"extra\":true,"));assertThrows(IllegalArgumentException.class,()->repo.load(i.snapshot().id()));Files.writeString(p,valid.replace("\"schemaVersion\":1","\"schemaVersion\":99"));assertThrows(IllegalArgumentException.class,()->repo.load(i.snapshot().id()));}
    @Test void caseFileIdentityMustMatchRequestedId()throws Exception{var i=ready();var repo=new JsonCaseRepository(temp);repo.save(i.snapshot());UUID other=UUID.randomUUID();Files.copy(casePath(temp,i.snapshot().id()),casePath(temp,other));assertThrows(IllegalArgumentException.class,()->repo.load(other));}
    @Test void runningCaseRestoresPausedAndRevalidationPreservesRevisionCeiling(){var i=ready();engine.acceptRulePlan(i);engine.acceptRulePlan(i);i.recordAction("STATE_CHANGED","RUNNING",List.of());var repo=new JsonCaseRepository(temp);repo.save(i.snapshot());var opened=repo.load(i.snapshot().id());assertEquals(CaseStatus.PAUSED,opened.snapshot().status());assertThrows(IllegalStateException.class,()->engine.run(opened));UUID planId=opened.snapshot().plan().id();engine.revalidate(opened);assertEquals(CaseStatus.READY,opened.snapshot().status());assertEquals(2,opened.snapshot().plan().revision());assertEquals(planId,opened.snapshot().plan().id());assertEquals(Completeness.COMPLETE,engine.run(opened).completeness());}
    @Test void pausedCaseRevalidationRejectsMissingDatasetVersion(){var i=ready();i.recordAction("STATE_CHANGED","RUNNING",List.of());var opened=Investigation.restore(i.snapshot());var empty=new DatasetStore("demo");try(var executor=ToolExecutor.local(empty)){assertThrows(PlanningException.class,()->engine(empty,executor).revalidate(opened));assertEquals(CaseStatus.PAUSED,opened.snapshot().status());}}
    @Test void controllerOpensRestoredCaseAndRequiresExplicitResume(){var i=ready();i.recordAction("STATE_CHANGED","RUNNING",List.of());var repo=new JsonCaseRepository(temp);repo.save(i.snapshot());var controller=new AgentController(engine,repo,new LogImporter(store),new ReportService(),new EventBus());controller.open(i.snapshot().id());assertThrows(IllegalStateException.class,()->controller.run(i.snapshot().id()));controller.resume(i.snapshot().id());assertEquals(CaseStatus.READY,controller.snapshot(i.snapshot().id()).status());}
    @Test void allDatasetVersionsAndFeedProvenanceRoundtrip(){store.ingest(new ImportBatch(List.of(event("b",1))));store.loadIndicatorFeed(Path.of("data/indicators/threat-feed.json"));var call=new ToolCall(UUID.randomUUID(),"indicatorLookup",Map.of("indicator","192.0.2.10","feedVersion","demo-feed-v1"));var indicator=new IndicatorLookupCommand(store).execute(call).evidence().get(0);Path p=temp.resolve("dataset.json");store.save(p);var restored=new DatasetStore("demo");restored.restore(p);assertEquals(store.events("v0"),restored.events("v0"));assertEquals(store.events("v1"),restored.events("v1"));assertEquals(store.events("v2"),restored.events("v2"));assertEquals("v2",restored.currentVersion());assertEquals(store.resolveIndicator(indicator),restored.resolveIndicator(indicator));assertTrue(restored.resolveIndicator(indicator).isPresent());}
    @Test void durableImportPersistsBeforePublishingNewVersion(){Path p=temp.resolve("dataset.json");store.durable(p);store.ingest(new ImportBatch(List.of(event("b",1))));var restored=new DatasetStore("demo");restored.restore(p);assertEquals("v2",restored.currentVersion());assertEquals(store.events("v2"),restored.events("v2"));}
    @Test void failedDurableImportLeavesMemoryAndExistingFileUnchanged()throws Exception{Path p=temp.resolve("dataset.json");store.save(p);String before=Files.readString(p);Path blocked=Files.writeString(temp.resolve("blocked"),"file");store.durable(blocked.resolve("dataset.json"));assertThrows(IllegalStateException.class,()->store.ingest(new ImportBatch(List.of(event("b",1)))));assertEquals("v1",store.currentVersion());assertEquals(before,Files.readString(p));}
    @Test void failedDurableFeedWriteDoesNotPublishFeed()throws Exception{Path blocked=Files.writeString(temp.resolve("blocked"),"file");store.durable(blocked.resolve("dataset.json"));assertThrows(IllegalStateException.class,()->store.loadIndicatorFeed(Path.of("data/indicators/threat-feed.json")));assertThrows(ToolException.class,()->new IndicatorLookupCommand(store).execute(new ToolCall(UUID.randomUUID(),"indicatorLookup",Map.of("indicator","192.0.2.10","feedVersion","demo-feed-v1"))));}
    @Test void invalidDatasetSchemaAndIdentityLeaveCurrentStateUnchanged()throws Exception{Path p=temp.resolve("data.json");store.save(p);String valid=Files.readString(p);for(String bad:List.of(valid.replace("\"schemaVersion\":1","\"schemaVersion\":99"),valid.replace("\"datasetId\":\"demo\"","\"datasetId\":\"other\""))){Files.writeString(p,bad);assertThrows(IllegalArgumentException.class,()->store.restore(p));assertEquals("v1",store.currentVersion());assertEquals(1,store.events("v1").size());}}
    @Test void persistedHistoryCannotDropEarlierEvents()throws Exception{store.ingest(new ImportBatch(List.of(event("b",1))));Path p=temp.resolve("data.json");store.save(p);var saved=JsonCodec.decode(Files.readString(p),DatasetStore.SavedDataset.class);var versions=new HashMap<>(saved.versions());versions.put("v2",List.of(saved.versions().get("v2").get(1)));Files.writeString(p,JsonCodec.encode(new DatasetStore.SavedDataset(1,"demo",2,versions,saved.feeds())));assertThrows(IllegalArgumentException.class,()->store.restore(p));assertEquals(2,store.events("v2").size());}
    @Test void persistedEventsCannotChangeIntroductionVersion()throws Exception{Path p=temp.resolve("data.json");store.save(p);String valid=Files.readString(p);Files.writeString(p,valid.replace("\"datasetVersion\":\"v1\"","\"datasetVersion\":\"v0\""));assertThrows(IllegalArgumentException.class,()->store.restore(p));assertEquals("v1",store.currentVersion());}
    @Test void strictUtf8DuplicateKeysAndTrailingJsonAreRejected()throws Exception{Path p=temp.resolve("file");Files.write(p,new byte[]{(byte)0xc3,(byte)0x28});assertThrows(IllegalStateException.class,()->AtomicFiles.read(p));assertThrows(IllegalArgumentException.class,()->JsonCodec.tree("{\"x\":1,\"x\":2}"));assertThrows(IllegalArgumentException.class,()->JsonCodec.tree("{} {}"));}
    @Test void noOverwriteAndFailedAtomicReplacePreservePriorOutput()throws Exception{Path p=temp.resolve("output.json");AtomicFiles.write(p,"old",false);assertThrows(IllegalStateException.class,()->AtomicFiles.write(p,"new",false));assertEquals("old",Files.readString(p));AtomicFiles.write(p,"new",true);assertEquals("new",Files.readString(p));Path directory=Files.createDirectory(temp.resolve("directory"));Files.writeString(directory.resolve("keep"),"keep");assertThrows(IllegalStateException.class,()->AtomicFiles.write(directory,"replacement",true));assertEquals("keep",Files.readString(directory.resolve("keep")));try(var entries=Files.list(temp)){assertFalse(entries.anyMatch(f->f.getFileName().toString().startsWith(".sentinel-")));}}
    @Test void oversizedWritePreservesExistingOutput()throws Exception{Path p=temp.resolve("output.json");AtomicFiles.write(p,"old",false);assertThrows(IllegalStateException.class,()->AtomicFiles.write(p,"x".repeat(20*1024*1024+1),true));assertEquals("old",Files.readString(p));}
}
